import re
from collections import Counter
c = Counter()
with open('/workspace/access.log') as fh:
    for line in fh:
        m = re.search(r'" (\d{3}) ', line)
        if m:
            c[m.group(1)] += 1
for code, n in c.most_common():
    print(code, n)

